SELECT 'core-2026-09-v4','determiners-quantifiers','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"determiners-quantifiers","title":"Determiners: some, any, each, all and neither","level":"A2","order":16,"summary":"Choose quantity and reference words from number, meaning and the type of noun phrase.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Some and any","Every and each","Both, either and neither","All, most and of"],"rules":[{"title":"Some and any","explanation":"Some is common in positive statements; any is common in negatives and open questions. Some is also natural in offers and requests when a positive response is anticipated. Any can mean it does not matter which in positive clauses.","pattern":"Would you like **some** tea? / Choose **any** seat.","commonMistakes":["Some and any are not fixed positive/negative opposites in every context."],"examples":["“Every book in this picture **has** a label.”","“Every box in this picture **has** a label.”"],"skill":"form"},{"title":"Every and each","explanation":"Every and each usually take a singular count noun and singular agreement. Every views the members as a complete group; each foregrounds them individually. Each of takes a plural noun phrase but the head each remains singular.","pattern":"**Every student has** a book. / **Each of the students has** one.","commonMistakes":["Every students mixes a singular determiner pattern with a plural noun."],"examples":["“Both books shown here **are** clearly labelled.”","“Both boxes shown here **are** clearly labelled.”"],"skill":"meaning"},{"title":"Both, either and neither","explanation":"Both refers to two together. Either selects one of two or leaves either choice open. Neither excludes both. Before a noun, either and neither usually take a singular count form; both takes plural. Usage after neither of can vary, especially informally.","pattern":"**Both seats are** free. / **Neither seat is** free.","commonMistakes":["Do not add not to neither merely to express the same negative meaning."],"examples":["“Most **of** the books in the picture are labelled.”","“Most **of** the boxes in the picture are labelled.”"],"skill":"contrast"},{"title":"All, most and of","explanation":"Use all or most directly before a general plural noun. Before a determiner or object pronoun, use an of-pattern where required: most of the books, all of them. All can often omit of before the: all the books.","pattern":"**Most books** / **Most of the books** / **All of them**","commonMistakes":["Most the books is missing of. Avoid assuming all and most have identical rules in every pattern."],"examples":["Exactly two books were considered, and neither was selected. What does “neither” mean here? → **Not one and not the other.**","Exactly two boxes were considered, and neither was selected. What does “neither” mean here? → **Not one and not the other.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Choose quantity and reference words from number, meaning and the type of noun phrase.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Some and any","explanation":"Some is common in positive statements; any is common in negatives and open questions. Some is also natural in offers and requests when a positive response is anticipated. Any can mean it does not matter which in positive clauses.","pattern":"Would you like **some** tea? / Choose **any** seat.","commonMistakes":["Some and any are not fixed positive/negative opposites in every context."],"examples":["“Every book in this picture **has** a label.”","“Every box in this picture **has** a label.”"],"skill":"form","id":"determiners-quantifiers-foundation-1","domain":"noun-phrases","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"title":"Every and each","explanation":"Every and each usually take a singular count noun and singular agreement. Every views the members as a complete group; each foregrounds them individually. Each of takes a plural noun phrase but the head each remains singular.","pattern":"**Every student has** a book. / **Each of the students has** one.","commonMistakes":["Every students mixes a singular determiner pattern with a plural noun."],"examples":["“Both books shown here **are** clearly labelled.”","“Both boxes shown here **are** clearly labelled.”"],"skill":"meaning","id":"determiners-quantifiers-foundation-2","domain":"noun-phrases","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"title":"Both, either and neither","explanation":"Both refers to two together. Either selects one of two or leaves either choice open. Neither excludes both. Before a noun, either and neither usually take a singular count form; both takes plural. Usage after neither of can vary, especially informally.","pattern":"**Both seats are** free. / **Neither seat is** free.","commonMistakes":["Do not add not to neither merely to express the same negative meaning."],"examples":["“Most **of** the books in the picture are labelled.”","“Most **of** the boxes in the picture are labelled.”"],"skill":"contrast","id":"determiners-quantifiers-foundation-3","domain":"noun-phrases","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"title":"All, most and of","explanation":"Use all or most directly before a general plural noun. Before a determiner or object pronoun, use an of-pattern where required: most of the books, all of them. All can often omit of before the: all the books.","pattern":"**Most books** / **Most of the books** / **All of them**","commonMistakes":["Most the books is missing of. Avoid assuming all and most have identical rules in every pattern."],"examples":["Exactly two books were considered, and neither was selected. What does “neither” mean here? → **Not one and not the other.**","Exactly two boxes were considered, and neither was selected. What does “neither” mean here? → **Not one and not the other.**"],"skill":"application","id":"determiners-quantifiers-foundation-4","domain":"noun-phrases","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"domain":"noun-phrases","id":"determiner-order","title":"Determiner slots, numbers and predeterminers","explanation":"A noun phrase usually has one central determiner, such as the, this or my. Some quantity words occur before it; numbers and ordinal expressions normally follow it. The order reflects the different jobs: identifying the group, locating an item within it, then counting or describing. Not every modifier belongs to the same slot.","pattern":"**all my three** children · **the first two** pages","examples":["**Both these** windows are open.","She read **my next three** messages."],"commonMistakes":["Do not stack ordinary central determiners: the my book and this a chair are not standard noun phrases. Use my book or this chair."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"noun-phrases","id":"some-any-context","title":"Some, any and their compound pronouns","explanation":"Some often presents an unspecified amount positively, including offers and requests expecting acceptance. Any often appears in open questions and negatives, but it also means unrestricted choice in positive clauses. Someone, anyone, something and anything show related patterns. The speaker’s intended meaning matters more than a positive/negative shortcut.","pattern":"Would you like **some**? / Choose **any** one.","examples":["Is there **anything** I can do?","**Anyone** with a ticket may enter."],"commonMistakes":["I didn’t buy any books normally means zero purchases. I didn’t buy some of the books means that particular members of a set were left unbought."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"noun-phrases","id":"quantifier-range","title":"Much, many, a lot, enough, several and plenty","explanation":"Many and several select plural count nouns; much selects non-count nouns. A lot of and plenty of work with both. Enough marks sufficiency and precedes a noun. Much is common in questions and negatives; a lot of is often more natural in ordinary affirmative conversation. Formal and modified uses allow much in affirmatives.","pattern":"**many books** / **much time** / **enough room**","examples":["We have **plenty of chairs** but **little space**.","There has been **much discussion** about the plan."],"commonMistakes":["Few/little and a few/a little differ in how they present the amount, not simply in whether the amount is mathematically small."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"noun-phrases","id":"distributive-partitive-numbers","title":"Each, every, all, whole, half and percentages","explanation":"Each foregrounds members individually; every covers all members of a set. All and whole can present completeness in different noun patterns. Fractions and percentages can refer to count or non-count quantities. In expressions such as half of the water or half of the students, the following noun often determines the practical agreement choice.","pattern":"**the whole day** / **all day**","examples":["**Half the cake is** left. / **Half the guests are** here.","**Every two weeks**, we meet again."],"commonMistakes":["Every is normally followed by a singular count noun, but every + number + plural noun expresses intervals: every three days."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"negation","id":"no-none-not-any","title":"No, none, nobody and not…any","explanation":"No is a determiner before a noun. None can stand alone or occur with of. Nobody, nothing and nowhere incorporate negative meaning. A negative verb with any-forms can often express a related message, but the focus and style may differ. Standard clauses ordinarily avoid a second negative expressing the same denial.","pattern":"**No visitors** arrived. / **Nobody** arrived.","examples":["There isn’t **any milk**. / There is **no milk**.","**None of these keys** fits the lock."],"commonMistakes":["With none of + plural noun, singular and plural agreement are both found according to emphasis and register. Avoid teaching only one as universally grammatical."],"referenceIds":["cambridge-negation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"negation","id":"negative-scope","title":"The scope of a negative","explanation":"Scope is the part of the meaning affected by a negative. Position and stress can change whether a whole event, an amount, a frequency or a reason is denied. A negative combined with all, every, always or necessarily often leaves some positive cases possible. Rephrase when the intended scope is unclear.","pattern":"**Not all** passed ≠ **None** passed","examples":["She does **not always** drive means there are occasions when she does not.","It is **not necessarily** expensive means expense is not guaranteed."],"commonMistakes":["All the guests didn’t come can be ambiguous in ordinary use. Write Not all the guests came or None of the guests came to state the intended meaning."],"referenceIds":["cambridge-negation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["Would you like **some** tea? / Choose **any** seat.","**Every student has** a book. / **Each of the students has** one.","**Both seats are** free. / **Neither seat is** free.","**Most books** / **Most of the books** / **All of them**"],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["small-quantities"],"readingReferenceIds":["bc-determiners","cambridge-comprehensive-scope","cambridge-negation"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='determiners-quantifiers'
